30	            "GroovyClassLoader|getClass|forName|getRuntime|exec\\(|" +
31	            "evaluate|invokeMethod|getMethods|getDeclaredMethod|" +
32	            "\\.class\\.|Class\\.|reflect\\.|invoke\\()",
